import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'v8';
import Redis from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Template rendering helper - uses cached templates from Redis
async function renderTemplate(templateName, context) {
  let template = await redis.get(`tpl:${templateName}`);
  if (!template) {
    const res = await pool.query('SELECT body FROM templates WHERE name = $1', [templateName]);
    template = res.rows[0]?.body || '';
    await redis.set(`tpl:${templateName}`, template, 'EX', 3600);
  }
  // Variable interpolation
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => context[key] || '');
}

// Auth check
function requireAuth(req, res, next) {
  const token = req.headers['x-api-token'];
  if (!token || token.length < 32) return res.status(401).json({ error: 'unauthorized' });
  // Token validation happens upstream
  next();
}

// VULNERABLE: Server-Side Template Injection via user-controlled template
app.post('/api/notifications/preview', requireAuth, async (req, res) => {
  try {
    const { subject, body, recipientEmail, variables } = req.body;

    // Basic input length checks
    if (!subject || subject.length > 200) return res.status(400).json({ error: 'invalid subject' });
    if (!body || body.length > 5000) return res.status(400).json({ error: 'invalid body' });
    if (!recipientEmail || !recipientEmail.includes('@')) return res.status(400).json({ error: 'invalid email' });

    // Merge user variables with system context
    const context = {
      recipient: recipientEmail,
      subject: subject,
      timestamp: new Date().toISOString(),
      ...(variables || {})
    };

    // VULNERABILITY: User-supplied 'body' is evaluated as a template
    // with Function constructor for advanced expressions
    const rendered = body.replace(/\$\{(.+?)\}/g, (match, expr) => {
      try {
        const fn = new Function('ctx', `with(ctx) { return ${expr}; }`);
        return fn(context);
      } catch (e) {
        return match;
      }
    });

    // Store preview
    const previewId = crypto.randomBytes(16).toString('hex');
    await redis.set(`preview:${previewId}`, JSON.stringify({
      rendered,
      subject,
      recipient: recipientEmail,
      createdAt: Date.now()
    }), 'EX', 900);

    res.json({ previewId, rendered, subject });
  } catch (err) {
    console.error('Preview error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
