// Fetch saved preview
app.get('/api/notifications/preview/:id', requireAuth, async (req, res) => {
  const data = await redis.get(`preview:${req.params.id}`);
  if (!data) return res.status(404).json({ error: 'not found' });
  res.json(JSON.parse(data));
});

// Send notification (uses stored templates only - safe)
app.post('/api/notifications/send', requireAuth, async (req, res) => {
  const { templateName, recipientEmail, variables } = req.body;
  if (!templateName || !recipientEmail) return res.status(400).json({ error: 'missing fields' });

  const context = { recipient: recipientEmail, ...(variables || {}) };
  const rendered = await renderTemplate(templateName, context);

  // Queue for sending
  await redis.lpush('email:queue', JSON.stringify({ to: recipientEmail, body: rendered }));
  res.json({ status: 'queued' });
});

app.listen(3000, () => console.log('Notification service running on :3000'));
